import json, math, unittest, tempfile
from pathlib import Path
import model

class TestLoadPayload(unittest.TestCase):
    def _w(self, text):
        d = tempfile.mkdtemp()
        p = Path(d) / "x.json"
        p.write_text(text, encoding="utf-8")
        return p

    def test_valid_object(self):
        p = self._w('{"a": 1, "b": [true, null, "x"]}')
        self.assertEqual(model.load_payload(p), {"a": 1, "b": [True, None, "x"]})

    def test_valid_array_top(self):
        p = self._w('[1, 2, 3]')
        self.assertEqual(model.load_payload(p), [1, 2, 3])

    def test_scalar_top_rejected(self):
        for t in ('1', '"x"', 'true', 'null'):
            with self.assertRaises(ValueError):
                model.load_payload(self._w(t))

    def test_invalid_json(self):
        with self.assertRaises(ValueError):
            model.load_payload(self._w('{oops'))

    def test_nan_rejected(self):
        with self.assertRaises(ValueError):
            model.load_payload(self._w('{"x": NaN}'))

    def test_infinity_rejected(self):
        with self.assertRaises(ValueError):
            model.load_payload(self._w('[Infinity]'))

    def test_nested_nan_rejected(self):
        with self.assertRaises(ValueError):
            model.load_payload(self._w('{"a": {"b": [1, -Infinity]}}'))

    def test_finite_float_ok(self):
        p = self._w('{"x": 1.5, "y": -2.0}')
        self.assertEqual(model.load_payload(p), {"x": 1.5, "y": -2.0})

if __name__ == '__main__':
    unittest.main()
